function Eyebrow({ children }: { children: React.ReactNode }) { return <div className="eyebrow">{children}</div>; }
function PageTitle({ overline, title, description }: { overline: string; title: string; description?: string }) { return <header className="page-title"><Eyebrow>{overline}</Eyebrow><h1>{title}</h1>{description && <p>{description}</p>}</header>; }
function SectionTitle({ kicker, title, copy }: { kicker: string; title: string; copy?: string }) { return <div className="section-title"><Eyebrow>{kicker}</Eyebrow><h2>{title}</h2>{copy && <p>{copy}</p>}</div>; }
function Label({ children }: { children: React.ReactNode }) { return <span className="field-label">{children}</span>; }
function NativeScript({ lang, children }: { lang: LangCode; children: React.ReactNode }) { return <span lang={lang} className={fontClasses[lang]}>{children}</span>; }
function Select({ label, value, onChange, options, id }: { label: string; value: string; onChange: (x: string) => void; options: readonly { value: string; label: string }[]; id: string }) { return <label className="select-wrap"><Label>{label}</Label><select id={id} value={value} onChange={(e) => onChange(e.target.value)} className="field-control">{options.map((opt) => <option value={opt.value} key={opt.value}>{opt.label}</option>)}</select></label>; }

const greetings: { code: LangCode; word: string }[] = [{ code: "en", word: "Hello" }, { code: "hi", word: "नमस्ते" }, { code: "ta", word: "வணக்கம்" }, { code: "te", word: "నమస్కారం" }, { code: "kn", word: "ನಮಸ್ಕಾರ" }, { code: "ml", word: "നമസ്കാരം" }];
const pipeline = ["Mic", "VAD", "Streaming ASR", "Language ID", "Code-mix / Term detection", "Adaptive segmentation", "Translation", "Caption stabilizer", "Optional TTS", "Metrics"];
const planned = new Set(["Language ID", "Code-mix / Term detection", "Optional TTS"]);

export function HomePage() {
  const [greetIndex, setGreetIndex] = useState(0); const [replay, setReplay] = useState(false); const [wordStep, setWordStep] = useState(0); const prefersReduced = useReducedMotion();
  useEffect(() => { if (prefersReduced) return; const id = window.setInterval(() => setGreetIndex((x) => (x + 1) % greetings.length), 2600); return () => window.clearInterval(id); }, [prefersReduced]);
  useEffect(() => { if (!replay || prefersReduced) return; const id = window.setInterval(() => setWordStep((x) => (x + 1) % 5), 1000); return () => window.clearInterval(id); }, [replay, prefersReduced]);
  return <div className="home-page">
    <section className="home-hero"><div className="hero-mesh" aria-hidden="true" /><CanvasRain /><div className="hero-content"><Eyebrow>REAL-TIME LANGUAGE BRIDGE <span className="tiny-separator" /> HACKNEX 2026</Eyebrow><div className="hello-line"><span>Say </span><AnimatePresence mode="wait"><motion.span key={greetIndex} initial={{ opacity: 0, y: 12, filter: "blur(8px)" }} animate={{ opacity: 1, y: 0, filter: "blur(0px)" }} exit={{ opacity: 0, y: -12, filter: "blur(8px)" }} transition={{ duration: prefersReduced ? 0 : .35 }}><NativeScript lang={greetings[greetIndex].code}>{greetings[greetIndex].word}</NativeScript></motion.span></AnimatePresence></div><h1>Speak any Indian language.<br /><span className={liveGradient}>Be understood in another,</span><br />as you speak.</h1><p className="hero-pitch">IndicLive is a real-time Indian-language communication bridge that makes live translation faster and more reliable by intelligently orchestrating streaming speech recognition, language detection, translation, code-mix handling and stable captions.</p><div className="hero-actions"><Button asChild size="lg"><Link to="/live"><Radio size={17} /> Try Live Translate</Link></Button><Button asChild variant="outline" size="lg"><Link to="/live?demo=1"><Play size={16} /> Watch Demo Replay</Link></Button><Button asChild variant="ghost" size="lg"><Link to="/benchmark">See Benchmark <ArrowRight size={16} /></Link></Button></div><div className="hero-meta"><span><span className="meta-dot" /> 6 languages</span><span>Streaming captions</span><span>Offline-first demo</span></div></div><div className="hero-signal" aria-hidden="true"><span>LIVE PIPELINE</span><div className="signal-bars">{Array.from({ length: 22 }, (_, i) => <i key={i} style={{ animationDelay: `${i * 44}ms` }} />)}</div><span>STABLE CAPTION ORCHESTRATION</span></div></section>
    <section className="section content-width challenge-section"><div className="two-col"><div><SectionTitle kicker="WHY THIS IS HARD" title="The last word changes everything." copy="Indian languages often place the verb at the end. A phrase can sound settled halfway through, then change meaning when the verb arrives." /><div className="inline-note"><Info size={16} /><span>Word order can shift from subject–verb–object to subject–object–verb.</span></div></div><div className="order-demo"><div className="order-head"><span>ENGLISH <small>S · V · O</small></span><span>TAMIL <small>S · O · V</small></span></div><div className="word-lanes"><div className="word-lane">{["I", "am", "going", "to Chennai", "tomorrow"].map((word, i) => <motion.span key={word} layout className={`word-chip ${wordStep === i ? "word-hot" : ""}`} transition={{ type: "spring", stiffness: 260, damping: 24 }}>{word}</motion.span>)}</div><div className="word-lane tamil-lane" lang="ta">{["நான்", "நாளை", "சென்னைக்கு", "போகிறேன்"].map((word, i) => <motion.span key={word} layout className={`word-chip ${wordStep === i + 1 ? "word-hot" : ""}`} transition={{ type: "spring", stiffness: 260, damping: 24 }}>{word}</motion.span>)}</div></div><div className="order-foot"><span className="teal-dot" /> The verb arrives last in Tamil, Hindi, Telugu, Kannada and Malayalam.</div><Button variant="ghost" size="sm" onClick={() => { setReplay(false); window.setTimeout(() => { setWordStep(0); setReplay(true); }, 10); }}><RotateCcw size={14} /> Replay</Button></div></div></section>
    <section className="section pipeline-section"><div className="content-width"><SectionTitle kicker="STREAMING ORCHESTRATION" title="A visible path from voice to stable words." copy="Each stage is labelled against the current backend contract. Planned steps remain clearly marked until data is available." /><div className="pipeline-track">{pipeline.map((item, i) => <div className={`pipeline-node ${planned.has(item) ? "planned" : ""}`} key={item}><span className="node-index">{String(i + 1).padStart(2, "0")}</span><span className="node-icon">{["Mic", "VAD", "Streaming ASR", "Language ID", "Code-mix / Term detection", "Adaptive segmentation", "Translation", "Caption stabilizer", "Optional TTS", "Metrics"][i].slice(0, 1)}</span><strong>{item}</strong><span className="status-label">{planned.has(item) ? "PLANNED" : "LIVE"}</span>{i < pipeline.length - 1 && <span className="pipeline-connector"><i /></span>}</div>)}</div><div className="pipeline-legend"><span><i className="legend-live" /> Backend contract</span><span><i className="legend-planned" /> Planned / not yet supplied</span></div></div></section>
    <section className="section content-width compare-section"><SectionTitle kicker="WHAT CHANGES" title="From a translation demo to a streaming instrument." /><div className="comparison-table"><div className="comparison-row comparison-header"><span>DIMENSION</span><span>Typical demo</span><span>IndicLive</span></div>{[["When it translates", "After full utterance", "Controlled partial commits"], ["Names and numbers", "Ordinary words", "Protected terms planned"], ["Language input", "Single language", "Code-mix aware · planned"], ["What is measured", "Quality only", "First word · final · stability"], ["Caption behavior", "May flicker", "Caption stabilization layer"]].map((r) => <div className="comparison-row" key={r[0]}><strong>{r[0]}</strong><span>{r[1]}</span><span className="comparison-good"><Check size={14} />{r[2]}</span></div>)}</div></section>
    <section className="section language-band"><div className="content-width language-inner"><span className="eyebrow">ONE BRIDGE · SIX LANGUAGES</span><div className="language-marquee">{LANGUAGES.map((language) => <span key={language.code}><NativeScript lang={language.code}>{language.native}</NativeScript><small>{language.name}</small></span>)}</div></div></section>
    <section className="closing-cta content-width"><div><Eyebrow>MAKE EVERY WORD COUNT</Eyebrow><h2>Stream speech.<br /><span className={liveGradient}>Keep meaning steady.</span></h2></div><Button asChild size="lg"><Link to="/live">Open Live Translate <ArrowRight size={16} /></Link></Button></section>
  </div>;
}

function CanvasRain() {
  const ref = useRef<HTMLCanvasElement>(null); const { settings } = useIndicStore();
  useEffect(() => { const canvas = ref.current; const context = canvas?.getContext("2d"); if (!canvas || !context || settings.reduceMotion) return; let raf = 0; let tick = 0; let cols: { x: number; y: number; speed: number; char: string }[] = []; const glyphs = ["அ", "अ", "అ", "ಅ", "അ", "A"];
    const resize = () => { const rect = canvas.getBoundingClientRect(); canvas.width = Math.floor(rect.width * devicePixelRatio); canvas.height = Math.floor(rect.height * devicePixelRatio); context.setTransform(devicePixelRatio, 0, 0, devicePixelRatio, 0, 0); cols = Array.from({ length: Math.ceil(rect.width / 30) }, (_, i) => ({ x: i * 30, y: Math.random() * rect.height, speed: .35 + Math.random() * .65, char: glyphs[Math.floor(Math.random() * glyphs.length)] ?? "A" })); };
    resize(); const observer = new ResizeObserver(resize); observer.observe(canvas); let visible = !document.hidden; const onVisibility = () => { visible = !document.hidden; if (visible) raf = requestAnimationFrame(draw); }; document.addEventListener("visibilitychange", onVisibility);
    const draw = () => { if (!visible) return; tick++; if (tick % 2 === 0) { const rect = canvas.getBoundingClientRect(); context.clearRect(0, 0, rect.width, rect.height); context.font = "16px sans-serif"; context.fillStyle = "rgba(214, 226, 245, 0.08)"; cols.forEach((col) => { context.fillText(col.char, col.x, col.y); col.y += col.speed * 1.5; if (col.y > rect.height) { col.y = -20; col.char = glyphs[Math.floor(Math.random() * glyphs.length)] ?? "A"; } }); } raf = requestAnimationFrame(draw); };
    raf = requestAnimationFrame(draw); return () => { cancelAnimationFrame(raf); observer.disconnect(); document.removeEventListener("visibilitychange", onVisibility); };
  }, [settings.reduceMotion]);
  return <canvas ref={ref} className="script-rain" aria-hidden="true" />;
}

const demoSets = [
  { id: "s1", title: "Verb-final", sourceLang: "ta" as LangCode, targetLang: "en" as LangCode, source: "நான் நாளை சென்னைக்கு போகிறேன்", annotation: "The verb arrives last, so the word order flips.", frames: [["", "I", false], ["", "I tomorrow", false], ["", "I tomorrow to Chennai", false], ["", "I am going to Chennai tomorrow", false], ["I am going to Chennai tomorrow", "", true]] as [string,string,boolean][], times: [.4,.8,1.2,1.6,2] },
  { id: "s2", title: "Code-mixed speech", sourceLang: "ta" as LangCode, targetLang: "en" as LangCode, source: "நாளைக்கு meeting இருக்கு so நான் late ஆ வருவேன்", annotation: "English words appear inside Tamil speech.", frames: [["", "Tomorrow", false], ["", "Tomorrow meeting", false], ["", "Tomorrow there's a meeting", false], ["I have a meeting tomorrow", "so I", false], ["I have a meeting tomorrow", "so I ... late", false], ["I have a meeting tomorrow so I will come late", "", true]] as [string,string,boolean][], times: [.4,.8,1.2,1.6,2,2.4] },
  { id: "s3", title: "Number protection", sourceLang: "hi" as LangCode, targetLang: "en" as LangCode, source: "कृपया अपना फोन नंबर नौ आठ सात छह पाँच बताइए", annotation: "Spoken digits remain visible as a protected number.", frames: [["", "Please", false], ["", "Please your", false], ["", "Please your phone number", false], ["", "Please your phone number 9", false], ["", "Please your phone number 9 8 7", false], ["", "Please your phone number 9 8 7 6 5", false], ["", "Please tell me your phone number: 9 8 7 6 5", false], ["Please tell me your phone number: 9 8 7 6 5", "", true]] as [string,string,boolean][], times: [.4,.8,1.2,1.6,2,2.4,2.8,3.2] },
];

function Caption({ frame, error, demo = false }: { frame: CaptionFrame | null; error: string; demo?: boolean }) {
  const committedWords = frame?.committed.trim().split(/\s+/).filter(Boolean) ?? []; const tentativeWords = frame?.tentative.trim().split(/\s+/).filter(Boolean) ?? [];
  return <div className="caption-body" aria-live="polite" aria-atomic="false">
    {demo && <div className="demo-badge"><span className="demo-dot" /> DEMO REPLAY · scripted · not live</div>}
    {error && <div className="error-banner" role="alert"><Info size={16} />{error}</div>}
    {committedWords.length + tentativeWords.length ? <div className="caption-words">{committedWords.map((word, i) => <motion.span key={`locked-${i}-${word}`} className="caption-word committed-word" initial={{ opacity: .65, scale: .96 }} animate={{ opacity: 1, scale: 1 }} transition={{ type: "spring", stiffness: 260, damping: 24 }}>{word}{i === committedWords.length - 1 && !tentativeWords.length ? <LockKeyhole className="lock-tick" size={12} /> : null}</motion.span>)}{tentativeWords.map((word, i) => <motion.span key={`tentative-${i}-${word}`} className="caption-word tentative-word" initial={{ opacity: .5 }} animate={{ opacity: [0.62, 1, .62] }} transition={{ duration: 1.7, repeat: Infinity }}>{word}</motion.span>)}</div> : <div className="caption-empty">{error ? "Waiting for the session to recover…" : "Your live translation will appear here."}</div>}
  </div>;
}

function Metric({ label, value, unit = "", detail }: { label: string; value: string | number; unit?: string; detail?: string }) { return <div className="metric-tile"><span className="metric-label">{label}</span><div className="metric-value">{value}<small>{unit}</small></div>{detail && <span className="metric-detail">{detail}</span>}<div className="metric-track"><i style={{ width: typeof value === "number" ? `${Math.max(0, Math.min(100, Number(value) / 1200 * 100))}%` : "0%" }} /></div></div>; }
function fmt(value: number | null | undefined, unit = "ms") { return value == null || !Number.isFinite(value) ? "–" : `${Math.round(value)}${unit}`; }

export function LivePage() {
  const { settings, glossary, setHistory, history, connectionStatus } = useIndicStore();
  const session = useIndicSession();
  const [src, setSrc] = useState<LangCode>("ta"); const [tgt, setTgt] = useState<LangCode>("en"); const [policy, setPolicy] = useState<Policy>(settings.policy); const [mode, setMode] = useState<"mic" | "sim">("mic"); const [inputText, setInputText] = useState(""); const [demo, setDemo] = useState(false); const [demoIndex, setDemoIndex] = useState(0); const [demoFrameIndex, setDemoFrameIndex] = useState(0); const [demoFrame, setDemoFrame] = useState<CaptionFrame | null>(null); const [demoSource, setDemoSource] = useState(""); const [lens, setLens] = useState<string[]>([]); const [compare, setCompare] = useState(false); const [sessionActive, setSessionActive] = useState(false); const [source, setSource] = useState(""); const [simSource, setSimSource] = useState("");
  const handleChunk = useCallback((buffer: ArrayBuffer) => { session.sendAudio(buffer); }, [session.sendAudio]); const handleSpeechEnd = useCallback(() => session.markSpeechEnd(), [session.markSpeechEnd]); const mic = useMicCapture(handleChunk, handleSpeechEnd);
  const currentDemo = demoSets[demoIndex] ?? demoSets[0]!;
  useEffect(() => { if (!demo) return; setDemoSource(""); setDemoFrame(null); setLens([]); setDemoFrameIndex(0); let index = 0; const next = () => { const d = demoSets[demoIndex] ?? demoSets[0]!; const step = d.frames[index]; if (!step) return; const [committed, tentative, final] = step; setDemoFrame({ t: d.times[index], committed, tentative, final, source: d.source }); setDemoSource(d.source.split(" ").slice(0, Math.max(1, index + 1)).join(" ")); setLens((old) => [...old.slice(-37), final ? "commit" : index > 1 ? "rewrite" : "tentative"]); index += 1; if (index < d.frames.length) window.setTimeout(next, 690); }; const id = window.setTimeout(next, 120); return () => window.clearTimeout(id); }, [demo, demoIndex]);
  const openSession = () => { setDemo(false); setSource(""); setSimSource(""); setSessionActive(true); session.connect(src, tgt, compare ? "stable" : policy); };
  const stopSession = () => { mic.stop(); session.stop(); setSessionActive(false); if (session.frame) saveSession("live", session.frame.committed, source, session.metrics, src, tgt, policy, history, setHistory); };
  const sendSim = () => { if (!inputText.trim()) return; if (!sessionActive) { openSession(); window.setTimeout(() => { if (!session.sendSimulation(inputText.trim())) toast.error("The backend is not connected. Check the WebSocket URL in Settings."); else setSimSource(inputText.trim()); }, 450); return; } if (session.sendSimulation(inputText.trim())) setSimSource(inputText.trim()); else toast.error("The backend is not connected. Check the WebSocket URL in Settings."); };
  const toggleDemo = () => { mic.stop(); session.stop(); setSessionActive(false); setDemoIndex(0); setDemo(true); setMode("sim"); };
  const saveDemo = () => { if (!demoFrame) return; saveSession("demo", `${demoFrame.committed} ${demoFrame.tentative}`.trim(), demoSource, { ...session.metrics, firstWordMs: null, finalMs: null }, currentDemo.sourceLang, currentDemo.targetLang, "scripted", history, setHistory); toast.success("Demo replay saved to History."); };
  const captionFrame = demo ? demoFrame : session.frame;
  const languageList = LANGUAGES.map((l) => ({ value: l.code, label: `${l.native} · ${l.name}` }));
  const displayedSource = demo ? demoSource : session.frame?.source ?? source;
  const terms = session.frame?.terms ?? [];
  return <div className="content-width page-content">
    <PageTitle overline="LIVE TRANSLATION" title="Make speech readable as it happens." description="A streaming caption instrument. Real results only when the backend is connected." />
    <div className="live-toolbar"><Select label="SOURCE" id="src-lang" value={src} onChange={(v) => setSrc(v as LangCode)} options={languageList} /><Button variant="outline" size="icon" title="Swap languages" aria-label="Swap languages" onClick={() => { setSrc(tgt); setTgt(src); }}><ArrowDownUp size={16} /></Button><Select label="TARGET" id="tgt-lang" value={tgt} onChange={(v) => setTgt(v as LangCode)} options={languageList} /><Select label="COMMIT POLICY" id="policy" value={policy} onChange={(v) => setPolicy(v as Policy)} options={POLICIES} /></div>
    <div className="live-mode-row"><div className="segmented-control"><Button variant={mode === "mic" ? "default" : "ghost"} onClick={() => { setMode("mic"); setDemo(false); }}> <Mic size={15} /> Microphone</Button><Button variant={mode === "sim" ? "default" : "ghost"} onClick={() => { setMode("sim"); mic.stop(); }}> <AudioLines size={15} /> Type to simulate</Button></div><label className="compare-toggle"><input type="checkbox" checked={compare} onChange={(e) => setCompare(e.target.checked)} /><span>Compare policies</span><small>Same ASR + MT, different commit policy.</small></label><div className={`status-chip status-${demo ? "demo" : session.status}`}><span className="status-dot" />{demo ? "Demo replay" : session.status === "live" ? "Live" : session.status === "connecting" ? "Connecting" : session.status === "error" ? "Error" : "Offline"}</div></div>
    <div className="live-layout">
      <div className="live-main">
        <section className="mic-console"><div className={`mic-ring ${mic.active ? "mic-active" : ""}`} style={{ "--mic-level": mic.level } as React.CSSProperties}><div className="ring-wave ring-a" /><div className="ring-wave ring-b" /><Button className="mic-button" size="icon" aria-label={mic.active ? "Stop microphone" : "Start microphone"} title={mic.active ? "Stop microphone" : "Start microphone"} onClick={async () => { if (!sessionActive) openSession(); if (mic.active) mic.stop(); else await mic.start(); }}><Mic size={26} /></Button></div><div className="mic-status">{mic.active ? <><span className="live-indicator" />Listening · {(mic.level * 100).toFixed(0)}% input level</> : sessionActive ? "Session connected · microphone paused" : "Start a live session"}</div>{mic.error && <div className="error-inline">{mic.error}</div>}{mode === "sim" && <div className="simulate-form"><textarea className="field-control" aria-label="Source-language sentence" placeholder="Enter a sentence in the selected source language…" value={inputText} onChange={(e) => setInputText(e.target.value)} /><Button onClick={sendSim} disabled={!inputText.trim()}><Send size={15} /> Send to backend</Button></div>}{sessionActive ? <Button variant="outline" onClick={stopSession}><Square size={14} /> Stop session</Button> : <Button onClick={openSession}><Radio size={15} /> Start live session</Button>}{session.error && <div className="offline-inline"><WifiOff size={17} /><div><strong>Backend offline</strong><p>{session.error}</p><code>uvicorn app.server:app --reload</code><p>Review the backend address in Settings.</p></div></div>}</section>
        <section className="caption-panel"><div className="panel-head"><div><Eyebrow>01 / SOURCE</Eyebrow><h3>Original</h3></div><span className="panel-tag">{locales[src]}</span></div><div className={`source-text ${displayedSource ? fontClasses[src] : "source-planned"}`} lang={src}>{displayedSource || "Source transcript: planned"}</div>{session.frame?.detected_lang && <span className="data-chip">Detected · {locales[session.frame.detected_lang as LangCode] ?? session.frame.detected_lang}</span>}</section>
        <section className="caption-panel translation-panel"><div className="panel-head"><div><Eyebrow>02 / TRANSLATION</Eyebrow><h3>Translation</h3></div><div className="panel-head-actions"><span className="panel-tag teal-tag">{demo ? "SCRIPTED" : policyLabel(policy)}</span><Button variant="ghost" size="icon" aria-label="Copy translation" title="Copy translation" disabled={!captionFrame} onClick={() => { void navigator.clipboard.writeText(`${captionFrame?.committed ?? ""} ${captionFrame?.tentative ?? ""}`.trim()); toast.success("Translation copied."); }}><Copy size={15} /></Button></div></div><Caption frame={captionFrame} error={demo ? "" : session.error} demo={demo} /><div className="commit-lens"><span className="metric-label">COMMIT LENS</span><div className="lens-bars" aria-label="Caption update stability"><AnimatePresence initial={false}>{lens.map((tick, i) => <motion.i key={`${i}-${tick}`} className={`lens-tick lens-${tick}`} initial={{ scaleY: .2, opacity: 0 }} animate={{ scaleY: 1, opacity: 1 }} exit={{ opacity: 0 }} title={tick === "commit" ? "Committed update" : tick === "rewrite" ? "Rewrite" : "Tentative update"} />)}</AnimatePresence>{!lens.length && <span className="lens-empty">Updates appear here</span>}</div></div></section>
        {compare && <div className="compare-split"><section className="caption-panel"><div className="panel-head"><h3>Baseline-style</h3><span className="panel-tag">sentence_end</span></div><Caption frame={null} error="Waiting for backend compare stream" /></section><section className="caption-panel"><div className="panel-head"><h3>IndicLive Stable</h3><span className="panel-tag teal-tag">stable</span></div><Caption frame={captionFrame} error="" /></section></div>}
        {demo && <div className="demo-controls"><span className="demo-badge"><span className="demo-dot" /> DEMO REPLAY · scripted · not live</span><span className="demo-annotation">{currentDemo.title} — {currentDemo.annotation}</span><Button variant="outline" onClick={() => setDemoIndex((demoIndex + 1) % demoSets.length)}><ChevronRight size={15} /> Next replay</Button><Button variant="ghost" onClick={() => { setDemo(false); setDemoFrame(null); }}>Exit demo</Button><Button variant="ghost" onClick={saveDemo}><Download size={14} /> Save to History</Button></div>}
      </div>
      <aside className="metrics-panel"><div className="panel-head"><div><Eyebrow>SESSION READOUT</Eyebrow><h3>Live metrics</h3></div><span className="status-chip"><span className="status-dot" />{demo ? "Demo" : connectionStatus}</span></div><div className="metrics-grid"><Metric label="First word" value={demo ? "–" : fmt(session.metrics.firstWordMs)} detail="audio sent → first caption" /><Metric label="Speech end → final" value={demo ? "–" : fmt(mode === "mic" ? session.metrics.finalMs : null)} detail={mode === "mic" ? "VAD end → final caption" : "Mic mode only"} /><Metric label="MT latency · last" value={demo ? "–" : fmt(session.metrics.mtLast)} detail={`avg ${fmt(session.metrics.mtAvg)} · p95 ${fmt(session.metrics.mtP95)}`} /><Metric label="Rewritten chars" value={demo ? "–" : session.metrics.rewrittenChars} detail={`${demo ? "–" : session.metrics.rewriteEvents} rewrite events`} /><Metric label="Commit ratio" value={demo ? "–" : fmt(session.metrics.commitRatio === null ? null : session.metrics.commitRatio * 100, "%")} detail="committed / displayed" /><Metric label="Updates / sec" value={demo ? "–" : fmt(session.metrics.updatesPerSecond, " /s")} detail="measured this session" /></div><div className="planned-readouts"><div><span>Detected language</span><b>{session.frame?.detected_lang ? locales[session.frame.detected_lang as LangCode] ?? session.frame.detected_lang : "PLANNED"}</b></div><div><span>Confidence</span><b>{session.frame?.confidence != null ? `${Math.round(session.frame.confidence * 100)}%` : "PLANNED"}</b></div><div><span>Code-mix</span><b>{displayedSource && /[a-zA-Z]/.test(displayedSource) ? "Present" : "–"}</b></div><div className="terms-row"><span>Protected terms</span>{terms.length ? terms.map((t) => <b className="term-chip" key={t}>{t}</b>) : <b>PLANNED</b>}</div></div><div className="policy-readout"><span>ACTIVE POLICY</span><strong>{policyLabel(policy)}</strong></div><div className="glossary-count"><BookOpen size={14} /> {glossary.length} terms will be sent on connect</div></aside>
    </div>
    <DemoScenarios onPlay={(index) => { setDemoIndex(index); setDemo(true); setMode("sim"); }} />
  </div>;
}
function policyLabel(policy: string) { return POLICIES.find((p) => p.value === policy)?.label ?? policy; }
function saveSession(mode: HistoryItem["mode"], transcript: string, sourceText: string, metrics: SessionMetrics, sourceLang: string, targetLang: string, policy: string, history: HistoryItem[], setter: (x: HistoryItem[]) => void) { setter([{ id: crypto.randomUUID(), date: new Date().toISOString(), sourceLang, targetLang, policy, mode, transcript: transcript.trim(), sourceText, metrics }, ...history]); toast.success("Session saved to History."); }
function DemoScenarios({ onPlay }: { onPlay: (index: number) => void }) { return <section className="demo-scenarios"><div className="panel-head"><div><Eyebrow>OFFLINE · SCRIPTED</Eyebrow><h3>Demo Replay</h3></div><span className="demo-badge"><span className="demo-dot" /> DEMO REPLAY · scripted · not live</span></div><div className="scenario-grid">{demoSets.map((scenario, i) => <button className="scenario-row" key={scenario.id} onClick={() => onPlay(i)}><span className="scenario-index">0{i + 1}</span><span className="scenario-text"><strong>{scenario.title}</strong><small><NativeScript lang={scenario.sourceLang}>{scenario.source}</NativeScript></small></span><Play size={15} /></button>)}</div></section>; }

function useMicCaptureLocal(onSpeech: (buffer: ArrayBuffer) => void) { const end = useCallback(() => {}, []); return useMicCapture((buffer) => onSpeech(buffer), end); }
export function ConversationPage() {
  const session = useIndicSession(); const { history, setHistory } = useIndicStore(); const [a, setA] = useState<LangCode>("ta"); const [b, setB] = useState<LangCode>("en"); const [active, setActive] = useState<"a" | "b" | null>(null); const [draft, setDraft] = useState(""); const [bubbles, setBubbles] = useState<{ speaker: string; text: string; translated: string; date: string }[]>([]);
  const handleSpeech = useCallback((buffer: ArrayBuffer) => session.sendAudio(buffer), [session.sendAudio]); const mic = useMicCaptureLocal(handleSpeech);
  const startTalk = (who: "a" | "b") => { if (active === who) { mic.stop(); session.stop(); setActive(null); if (session.frame?.final) { const item = { speaker: who, text: draft, translated: session.frame.committed, date: new Date().toISOString() }; setBubbles((v) => [...v, item]); saveSession("live", session.frame.committed, draft, session.metrics, who === "a" ? a : b, who === "a" ? b : a, "stable", history, setHistory); } return; } mic.stop(); session.stop(); setActive(who); const from = who === "a" ? a : b; session.connect(from, who === "a" ? b : a, "stable"); void mic.start(); };
  const languages = LANGUAGES.map((l) => ({ value: l.code, label: `${l.native} · ${l.name}` }));
  return <div className="content-width page-content"><PageTitle overline="TWO-WAY CONVERSATION" title="Let both speakers stay in the conversation." description="One speaker at a time. Each listener sees the translation on their side." /><div className="conversation-toolbar"><label className="planned-switch"><input type="checkbox" disabled /><span>Auto turn detection</span><small title="Needs backend support">PLANNED</small></label><div className="status-chip"><span className="status-dot" />{session.status}</div></div><div className="speaker-grid">{(["a", "b"] as const).map((who) => { const from = who === "a" ? a : b; const to = who === "a" ? b : a; const isTalking = active === who; const listener = active && active !== who; return <section className={`speaker-card ${isTalking ? "speaker-active" : ""}`} key={who}><div className="speaker-head"><div><Eyebrow>SPEAKER {who.toUpperCase()}</Eyebrow><h2>{locales[from]}</h2></div><span className={`speaker-avatar ${who}`}>{who.toUpperCase()}</span></div><Select label="SPEAKING LANGUAGE" id={`speaker-${who}`} value={from} onChange={(v) => who === "a" ? setA(v as LangCode) : setB(v as LangCode)} options={languages} /><div className={`speaker-wave ${isTalking ? "wave-on" : ""}`} aria-hidden="true">{Array.from({ length: 36 }, (_, i) => <i key={i} style={{ height: isTalking ? `${14 + ((i * 19) % 46)}%` : `${8 + ((i * 9) % 20)}%` }} />)}</div><div className="speaker-caption"><span className="metric-label">{listener ? "LISTENER VIEW · TRANSLATION" : isTalking ? "SPEAKING · LIVE CAPTION" : "LISTENER VIEW"}</span><p lang={listener ? to : from} className={fontClasses[listener ? to : from]}>{listener ? session.frame?.committed || session.frame?.tentative || "Waiting for translation…" : isTalking ? session.frame?.source ?? "Listening…" : "Ready for next turn"}</p></div><label className="field-label" htmlFor={`text-${who}`}>Optional typed source text</label><textarea id={`text-${who}`} className="field-control" value={isTalking ? draft : undefined} onChange={(e) => setDraft(e.target.value)} placeholder="For the backend sim mode, enter text here…" disabled={!isTalking} /><Button className="speaker-mic" onClick={() => startTalk(who)} variant={isTalking ? "destructive" : "default"}>{isTalking ? <><MicOff size={16} /> End turn</> : <><Mic size={16} /> Push to talk</>}</Button>{mic.error && isTalking && <p className="error-inline">{mic.error}</p>}<span className="target-note">Translates to {locales[to]}</span></section>; })}</div><section className="timeline-section"><div className="panel-head"><div><Eyebrow>SHARED TRANSCRIPT</Eyebrow><h3>Conversation timeline</h3></div><span className="panel-tag">{bubbles.length} turns</span></div>{bubbles.length ? <div className="timeline-list">{bubbles.map((bubble, i) => <div className={`chat-turn turn-${bubble.speaker}`} key={`${bubble.date}-${i}`}><span className="turn-name">Speaker {bubble.speaker.toUpperCase()}</span><p>{bubble.text}</p><p className="turn-translation">{bubble.translated}</p><small>{new Date(bubble.date).toLocaleTimeString()}</small></div>)}</div> : <div className="empty-inline"><MessageEmpty />Final captions will appear here after a speaker finishes a turn.</div>}</section></div>;
}
function MessageEmpty() { return <span className="empty-icon"><Languages size={16} /></span>; }

export function GlossaryPage() {
  const { glossary, setGlossary } = useIndicStore(); const [search, setSearch] = useState(""); const [source, setSource] = useState(""); const [target, setTarget] = useState(""); const [category, setCategory] = useState("Name"); const [filter, setFilter] = useState("All"); const [editing, setEditing] = useState<string | null>(null);
  const visible = glossary.filter((t) => `${t.source} ${t.target}`.toLowerCase().includes(search.toLowerCase()) && (filter === "All" || t.category === filter));
  const add = () => { if (!source.trim() || !target.trim()) return; if (editing) setGlossary(glossary.map((g) => g.id === editing ? { ...g, source: source.trim(), target: target.trim(), category } : g)); else setGlossary([{ id: crypto.randomUUID(), source: source.trim(), target: target.trim(), category }, ...glossary]); setSource(""); setTarget(""); setEditing(null); toast.success(editing ? "Term updated." : "Term added."); };
  const exportFile = () => downloadFile("indiclive-glossary.json", JSON.stringify(glossary, null, 2), "application/json");
  const importFile = async (file?: File) => { if (!file) return; try { const rows = JSON.parse(await file.text()) as GlossaryTerm[]; if (!Array.isArray(rows)) throw new Error(); setGlossary([...rows.map((r) => ({ id: crypto.randomUUID(), source: String(r.source), target: String(r.target), category: String(r.category ?? "Name") })), ...glossary]); toast.success(`Imported ${rows.length} terms.`); } catch { toast.error("That JSON file could not be imported."); } };
  return <div className="content-width page-content"><PageTitle overline="TERM PROTECTION" title="Keep important words intact." description="Maintain preferred equivalents for names, places, technical terms, and products." /><div className="glossary-layout"><section className="glossary-form-section"><div className="panel-head"><div><Eyebrow>ADD A TERM</Eyebrow><h3>{editing ? "Edit entry" : "Glossary entry"}</h3></div><span className="field-counter">{glossary.length} terms</span></div><div className="form-grid"><label><Label>Source term</Label><input className="field-control" value={source} onChange={(e) => setSource(e.target.value)} placeholder="e.g. IndicLive" /></label><label><Label>Preferred target</Label><input className="field-control" value={target} onChange={(e) => setTarget(e.target.value)} placeholder="e.g. IndicLive" /></label><label><Label>Category</Label><select className="field-control" value={category} onChange={(e) => setCategory(e.target.value)}>{["Name", "Place", "Technical", "Product"].map((x) => <option key={x}>{x}</option>)}</select></label><Button onClick={add} disabled={!source.trim() || !target.trim()}><Plus size={15} />{editing ? "Save changes" : "Add term"}</Button></div></section><section className="glossary-list-section"><div className="glossary-list-toolbar"><div className="search-field"><Search size={15} /><input aria-label="Search glossary" value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search terms…" /></div><select className="field-control filter-select" aria-label="Filter glossary category" value={filter} onChange={(e) => setFilter(e.target.value)}>{["All", "Name", "Place", "Technical", "Product"].map((x) => <option key={x}>{x}</option>)}</select><Button variant="outline" onClick={exportFile}><Download size={14} />Export</Button><label className="button-label"><Upload size={14} />Import<input type="file" accept="application/json,.json" onChange={(e) => void importFile(e.target.files?.[0])} /></label></div><div className="table-scroll"><table className="data-table"><thead><tr><th>Source</th><th>Preferred target</th><th>Category</th><th>Actions</th></tr></thead><tbody>{visible.map((term) => <tr key={term.id}><td>{term.source}</td><td>{term.target}</td><td><span className="category-chip">{term.category}</span></td><td><div className="row-actions"><Button variant="ghost" size="icon" aria-label={`Edit ${term.source}`} onClick={() => { setEditing(term.id); setSource(term.source); setTarget(term.target); setCategory(term.category); }}><Info size={14} /></Button><Button variant="ghost" size="icon" aria-label={`Remove ${term.source}`} onClick={() => setGlossary(glossary.filter((g) => g.id !== term.id))}><Trash2 size={14} /></Button></div></td></tr>)}{!visible.length && <tr><td colSpan={4} className="empty-cell">No matching glossary terms.</td></tr>}</tbody></table></div></section></div><div className="notice-line"><Info size={15} />Glossary terms are included in the backend connection message. Term protection remains planned until the backend returns protected-term data.</div></div>;
}

function downloadFile(name: string, text: string, type: string) { const url = URL.createObjectURL(new Blob([text], { type })); const link = document.createElement("a"); link.href = url; link.download = name; link.click(); URL.revokeObjectURL(url); }
function parseCsv(text: string): BenchmarkRow[] { const rows = text.trim().split(/\r?\n/).map((line) => line.split(",").map((cell) => cell.trim().replace(/^"|"$/g, ""))); const header = rows.shift()?.map((s) => s.toLowerCase()) ?? []; const required = ["config", "ttfw", "final_lat", "flicker", "revisions", "chrf", "mt", "n_utterances"]; if (!required.every((x) => header.includes(x))) throw new Error("CSV headers do not match the expected benchmark fields."); return rows.map((cells) => Object.fromEntries(required.map((key) => { const value = cells[header.indexOf(key)] ?? ""; return [key, ["config", "mt"].includes(key) ? value : Number(value)]; })) as BenchmarkRow); }
export function BenchmarkPage() {
  const { benchmark, setBenchmark } = useIndicStore(); const [paste, setPaste] = useState(""); const [modalOpen, setModalOpen] = useState(false); const [sort, setSort] = useState<keyof BenchmarkRow>("ttfw"); const [asc, setAsc] = useState(true);
  const importText = (text: string) => { try { const parsed = text.trim().startsWith("[") ? JSON.parse(text) as BenchmarkRow[] : parseCsv(text); if (!Array.isArray(parsed) || !parsed.every((r) => typeof r.config === "string" && Number.isFinite(r.ttfw) && Number.isFinite(r.final_lat))) throw new Error("Missing expected fields."); setBenchmark(parsed); setModalOpen(false); toast.success(`Imported ${parsed.length} benchmark rows.`); } catch (e) { toast.error(e instanceof Error ? e.message : "Could not import results."); } };
  const rows = [...benchmark].sort((x, y) => { const a = x[sort]; const b = y[sort]; return (typeof a === "number" && typeof b === "number" ? a - b : String(a).localeCompare(String(b))) * (asc ? 1 : -1); });
  const chartRows = benchmark.map((r) => ({ config: r.config, "First caption": r.ttfw, "Final latency": r.final_lat, "Chars rewritten": r.flicker, "chrF++": r.chrf }));
  const bestFor = (key: keyof BenchmarkRow) => { if (!benchmark.length) return null; const values = benchmark.map((r) => Number(r[key])); return key === "chrf" ? Math.max(...values) : Math.min(...values); };
  return <div className="content-width page-content"><PageTitle overline="CONTROLLED EVALUATION" title="Benchmark what the system actually does." description="Only imported evaluation results appear here. Demo replays and live sessions are never benchmark data." />{benchmark.length ? <><div className="benchmark-toolbar"><span className="data-count"><span className="teal-dot" />{benchmark.length} imported configurations</span><Button variant="outline" onClick={() => setModalOpen(true)}><FileUp size={15} />Import results</Button></div><section className="chart-section"><div className="panel-head"><div><Eyebrow>RESULTS · IMPORTED</Eyebrow><h3>Configuration comparison</h3></div><span className="panel-tag">{benchmark.length} rows</span></div><div className="chart-grid"><Chart title="Caption and final timing" data={chartRows} series={["First caption", "Final latency"]} colors={["var(--chart-saffron)", "var(--chart-rose)"]} /><Chart title="Stability and translation quality" data={chartRows} series={["Chars rewritten", "chrF++"]} colors={["var(--chart-teal)", "var(--chart-violet)"]} /></div></section><section className="benchmark-table-section"><div className="panel-head"><div><Eyebrow>RAW RESULTS</Eyebrow><h3>Sortable results</h3></div></div><div className="table-scroll"><table className="data-table"><thead><tr>{[["config","Configuration"],["ttfw","First caption"],["final_lat","Final latency"],["flicker","Rewritten chars"],["revisions","Revisions"],["chrf","chrF++"],["mt","MT"],["n_utterances","Utterances"]].map(([key,label]) => <th key={key}><button className="sort-button" onClick={() => { if (sort === key) setAsc(!asc); else { setSort(key as keyof BenchmarkRow); setAsc(true); } }}>{label}<ChevronRight size={12} /></button></th>)}</tr></thead><tbody>{rows.map((r,i) => <tr key={`${r.config}-${i}`}><td><strong>{r.config}</strong></td><td className={r.ttfw === bestFor("ttfw") ? "best-value" : ""}>{r.ttfw}</td><td className={r.final_lat === bestFor("final_lat") ? "best-value" : ""}>{r.final_lat}</td><td className={r.flicker === bestFor("flicker") ? "best-value" : ""}>{r.flicker}</td><td>{r.revisions}</td><td className={r.chrf === bestFor("chrf") ? "best-value" : ""}>{r.chrf}</td><td>{r.mt === "mock" ? <span className="warning-chip">mock · quality not meaningful</span> : r.mt}</td><td>{r.n_utterances}</td></tr>)}</tbody></table></div></section></> : <section className="benchmark-empty"><div className="empty-icon large"><BarChart3 size={23} /></div><Eyebrow>NO IMPORTED RESULTS</Eyebrow><h2>No benchmark data yet.</h2><p>Run the evaluation script, then import its JSON or CSV output. Nothing is estimated or pre-filled.</p><code>python -m eval.run_eval --mt azure --json results.json</code><div><Button onClick={() => setModalOpen(true)}><FileUp size={15} />Import results</Button></div></section>}
    <section className="ablation-section"><div className="panel-head"><div><Eyebrow>EXPERIMENT PLAN</Eyebrow><h3>Ablation roadmap</h3></div><span className="panel-tag">A—E</span></div><div className="ablation-list">{["A · Complete-sentence baseline", "B · Streaming without stabilization", "C · Streaming + adaptive segmentation", "D · + term protection + caption stabilization", "E · Full system + code-mix + language ID"].map((x,i)=><div className="ablation-row" key={x}><span>{String.fromCharCode(65+i)}</span><strong>{x.slice(4)}</strong><small>PLANNED</small></div>)}</div></section>
    <AnimatePresence>{modalOpen && <ImportDialog paste={paste} setPaste={setPaste} onClose={() => setModalOpen(false)} onImport={importText} onFile={(file) => { if (file) void file.text().then(importText); }} />}</AnimatePresence></div>;
}
function Chart({ title, data, series, colors }: { title: string; data: Record<string, string | number>[]; series: string[]; colors: string[] }) { return <div className="chart-panel"><div className="chart-title">{title}</div><ResponsiveContainer width="100%" height={245}><BarChart data={data} margin={{ top: 12, right: 10, bottom: 2, left: -12 }}><CartesianGrid stroke="var(--border)" vertical={false} /><XAxis dataKey="config" stroke="var(--muted-foreground)" fontSize={11} tickLine={false} axisLine={false} /><YAxis stroke="var(--muted-foreground)" fontSize={10} tickLine={false} axisLine={false} /><Tooltip contentStyle={{ background: "var(--surface-2)", border: "1px solid var(--border)", borderRadius: 8 }} /><Legend wrapperStyle={{ fontSize: 11 }} />{series.map((s,i)=><Bar key={s} dataKey={s} fill={colors[i]} radius={[3,3,0,0]} />)}</BarChart></ResponsiveContainer></div>; }
function ImportDialog({ paste, setPaste, onClose, onImport, onFile }: { paste: string; setPaste:(v:string)=>void; onClose:()=>void; onImport:(v:string)=>void; onFile:(f?:File)=>void }) { return <><motion.button className="drawer-scrim" aria-label="Close import dialog" onClick={onClose} initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}}/><motion.div className="import-dialog" role="dialog" aria-modal="true" aria-labelledby="import-title" initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} exit={{opacity:0,y:12}}><div className="panel-head"><div><Eyebrow>BENCHMARK DATA</Eyebrow><h3 id="import-title">Import results</h3></div><Button variant="ghost" size="icon" aria-label="Close" onClick={onClose}><X size={16}/></Button></div><label className="button-label import-file"><FileJson size={16}/>Choose JSON or CSV<input type="file" accept="application/json,.json,.csv,text/csv" onChange={(e)=>onFile(e.target.files?.[0])}/></label><Label>Or paste a JSON array / matching CSV</Label><textarea className="field-control import-textarea" value={paste} onChange={(e)=>setPaste(e.target.value)} placeholder='[{"config":"A","ttfw":0,...}]'/><div className="dialog-actions"><Button variant="outline" onClick={onClose}>Cancel</Button><Button onClick={()=>onImport(paste)} disabled={!paste.trim()}><Upload size={14}/>Import pasted results</Button></div></motion.div></>; }

export function HistoryPage() {
  const { history, setHistory } = useIndicStore(); const [query,setQuery]=useState(""); const [mode,setMode]=useState("All"); const [expanded,setExpanded]=useState<string | null>(null);
  const rows=history.filter((item)=>`${item.transcript} ${item.sourceText} ${item.sourceLang} ${item.targetLang}`.toLowerCase().includes(query.toLowerCase())&&(mode==="All"||item.mode===mode.toLowerCase()));
  const exportData=(type:"json"|"csv")=>{ if(type==="json") downloadFile("indiclive-history.json",JSON.stringify(history,null,2),"application/json"); else { const header="date,source,target,policy,mode,transcript,first_word_ms,final_ms,mt_avg,rewritten_chars,commit_ratio"; const lines=history.map((h)=>[h.date,h.sourceLang,h.targetLang,h.policy,h.mode,`"${h.transcript.replaceAll('"','""')}"`,h.metrics.firstWordMs??"",h.metrics.finalMs??"",h.metrics.mtAvg??"",h.metrics.rewrittenChars,h.metrics.commitRatio??""].join(",")); downloadFile("indiclive-history.csv",[header,...lines].join("\n"),"text/csv"); }};
  return <div className="content-width page-content"><PageTitle overline="SESSION ARCHIVE" title="History, without mixing demo and live." description="Saved sessions retain their mode badge and measured metrics for later review." /><div className="history-toolbar"><div className="search-field"><Search size={15}/><input aria-label="Search sessions" value={query} onChange={(e)=>setQuery(e.target.value)} placeholder="Search transcripts…"/></div><select className="field-control filter-select" aria-label="Filter history mode" value={mode} onChange={(e)=>setMode(e.target.value)}>{["All","Live","Simulated","Demo"].map((x)=><option key={x}>{x}</option>)}</select><Button variant="outline" onClick={()=>exportData("json")}><Download size={14}/>JSON</Button><Button variant="outline" onClick={()=>exportData("csv")}><Download size={14}/>CSV</Button></div>{rows.length?<div className="history-list">{rows.map((item)=><article className="history-item" key={item.id}><button className="history-item-head" onClick={()=>setExpanded(expanded===item.id?null:item.id)}><span className="history-date">{new Date(item.date).toLocaleString()}</span><span className={`mode-pill mode-${item.mode}`}>{item.mode}</span><span className="history-languages">{locales[item.sourceLang as LangCode]??item.sourceLang}<ArrowRight size={13}/>{locales[item.targetLang as LangCode]??item.targetLang}</span><strong>{item.transcript||"No final caption saved"}</strong><ChevronRight className={expanded===item.id?"rotate-chevron":""} size={16}/></button><AnimatePresence>{expanded===item.id&&<motion.div className="history-details" initial={{height:0,opacity:0}} animate={{height:"auto",opacity:1}} exit={{height:0,opacity:0}}><div><span>Policy</span><b>{item.policy}</b></div><div><span>First word</span><b>{fmt(item.metrics.firstWordMs)}</b></div><div><span>End → final</span><b>{fmt(item.metrics.finalMs)}</b></div><div><span>MT average</span><b>{fmt(item.metrics.mtAvg)}</b></div><div><span>Rewritten chars</span><b>{item.metrics.rewrittenChars}</b></div><div><span>Commit ratio</span><b>{fmt(item.metrics.commitRatio===null?null:item.metrics.commitRatio*100,"%")}</b></div>{item.sourceText&&<p className={fontClasses[item.sourceLang as LangCode]}>{item.sourceText}</p>}<Button variant="ghost" size="sm" onClick={()=>setHistory(history.filter((x)=>x.id!==item.id))}><Trash2 size={14}/>Delete session</Button></motion.div>}</AnimatePresence></article>)}</div>:<section className="benchmark-empty"><div className="empty-icon large"><Activity size={23}/></div><Eyebrow>NO SAVED SESSIONS</Eyebrow><h2>{history.length?"No sessions match those filters.":"Your saved sessions will appear here."}</h2><p>Run a real or scripted session, then save it to return to its transcript and measurements.</p><Button asChild><Link to="/live">Open Live Translate</Link></Button></section>}</div>;
}

const architecture: [string,string][] = [["Frontend", "LIVE"],["Audio / Streaming", "LIVE"],["VAD / Segmentation", "LIVE"],["ASR", "LIVE"],["Language ID", "PLANNED"],["Translation", "LIVE"],["Term protection", "PLANNED"],["Caption stabilizer", "LIVE"],["TTS", "PLANNED"],["Evaluation", "PLANNED"]];
export function AboutPage() {
  return <div className="content-width page-content"><PageTitle overline="ABOUT THE RESEARCH" title="Measure the orchestration, not just the output." description="IndicLive is built for HackNex 2026 problem HNX26EPS03: live translation between Indian languages and English."/><section className="about-pitch"><Eyebrow>THE CONTRIBUTION</Eyebrow><p>IndicLive is a real-time Indian-language communication bridge that makes live translation faster and more reliable by intelligently orchestrating streaming speech recognition, language detection, translation, code-mix handling and stable captions.</p></section><div className="about-grid"><section className="architecture-section"><div className="panel-head"><div><Eyebrow>CAPABILITY MAP</Eyebrow><h3>Architecture status</h3></div></div><div className="architecture-list">{architecture.map(([name,status],i)=><div className="architecture-row" key={name}><span>{String(i+1).padStart(2,"0")}</span><strong>{name}</strong><i/><b className={status==="PLANNED"?"planned-chip":"live-chip"}>{status}</b></div>)}</div><div className="workflow-line">Mic → VAD → ASR → Adaptive segmentation → Translation → Caption stabilizer → Metrics</div></section><section className="claims-section"><div className="panel-head"><div><Eyebrow>RESEARCH INTEGRITY</Eyebrow><h3>What we claim / what we don't</h3></div><ShieldCheck size={18}/></div><ul><li><Check size={15}/>We measure the current backend stream and label data by source.</li><li><X size={15}/>We don't claim competitors cannot translate these languages.</li><li><X size={15}/>We don't claim faster results without identical-input benchmarks.</li><li><X size={15}/>We don't invent translation, latency, or quality numbers.</li><li><X size={15}/>The UI is not the innovation; the orchestration is.</li></ul></section></div><section className="ablation-section"><div className="panel-head"><div><Eyebrow>CONTROLLED EXPERIMENTS</Eyebrow><h3>Evaluation plan</h3></div></div><div className="ablation-list">{["A · Complete-sentence baseline", "B · Streaming without stabilization", "C · Streaming + adaptive segmentation", "D · + term protection + caption stabilization", "E · Full system + code-mix + language ID"].map((x,i)=><div className="ablation-row" key={x}><span>{String.fromCharCode(65+i)}</span><strong>{x.slice(4)}</strong><small>PLANNED</small></div>)}</div></section><section className="judge-answer"><Eyebrow>THE JUDGE QUESTION</Eyebrow><h2>“Why not just Google Translate?”</h2><blockquote>We are not claiming Google cannot translate Indian languages. Our focus is different. IndicLive is designed and evaluated specifically for real-time spoken Indian-language communication. Our contribution is the streaming orchestration layer: deciding when partial speech is stable enough to translate, handling code-mixed speech, protecting names and numbers, reducing caption rewrites, and measuring first-word and final latency. We will prove the improvement through a controlled baseline comparison rather than just claiming it.</blockquote></section></div>;
}